import { SVGIcon } from '@progress/kendo-react-common';
import { AgentStepExpandedChangeEvent } from '../Events';
import { AgentStepHeaderTemplateProps } from './AgentStepHeaderTemplateProps';
import { AgentStepBodyTemplateProps } from './AgentStepBodyTemplateProps';
import * as React from 'react';
/**
 * Defines the props for the `AgentStep`-based step components:
 * `Reasoning`, `ChainOfThought`, and `ToolCall`.
 *
 * Extends `React.HTMLAttributes<HTMLDivElement>` to allow passing standard HTML
 * attributes (e.g. `className`, `style`, `children`, `id`) directly to the root element.
 *
 * @hidden
 */
export interface AgentStepProps extends React.HTMLAttributes<HTMLDivElement> {
    /**
     * The SVG icon displayed in the step header.
     * Pass an icon object from `@progress/kendo-svg-icons`.
     *
     * @example
     * ```tsx
     * import { brainIcon } from '@progress/kendo-svg-icons';
     * <Reasoning svgIcon={brainIcon} />
     * ```
     */
    svgIcon?: SVGIcon;
    /**
     * The primary label text displayed in the step header.
     */
    label?: string;
    /**
     * An optional CSS class name applied to the label `<span>` element in the step header.
     */
    labelClassName?: string;
    /**
     * An optional secondary label displayed below or alongside the primary label,
     * typically used to show a brief summary of the step (e.g. number of thoughts,
     * file path, or duration text).
     */
    secondaryLabel?: string;
    /**
     * The number of lines added during this step, shown as a green diff indicator.
     * Typically used in `ToolCall` or code-generating steps.
     */
    linesAdded?: number;
    /**
     * The number of lines removed during this step, shown as a red diff indicator.
     * Typically used in `ToolCall` or code-modifying steps.
     */
    linesRemoved?: number;
    /**
     * When `true`, the step header renders a toggle button that allows
     * the user to expand or collapse the step body.
     *
     * @default false
     */
    expandable?: boolean;
    /**
     * Controls the expanded state of the step in controlled mode.
     * Use together with `onExpandedChange` to manage state externally.
     * When provided, the component behaves as a controlled component.
     */
    expanded?: boolean;
    /**
     * The initial expanded state of the step when used in uncontrolled mode.
     * Ignored when `expanded` is provided.
     * Defaults to `false`.
     */
    defaultExpanded?: boolean;
    /**
     * When `true`, the step is marked as completed.
     * Completed steps may render with a distinct visual treatment (e.g. a check icon).
     */
    completed?: boolean;
    /**
     * Callback fired when the user expands or collapses the step.
     * Receives an `AgentStepExpandedChangeEvent` with the new `expanded` state.
     *
     * @example
     * ```tsx
     * <Reasoning onExpandedChange={(e) => setExpanded(e.expanded)} />
     * ```
     */
    onExpandedChange?: (event: AgentStepExpandedChangeEvent) => void;
    /**
     * Additional content rendered inside the step header content area, after the
     * label, secondary label, and line-count indicators, and before the expand
     * indicator. Intended for persistent header UI such as the `ToolCall` status badge.
     *
     * @hidden
     */
    headerExtra?: React.ReactNode;
    /**
     * A custom component that replaces the default step header row.
     * Receives all header data props via `AgentStepHeaderTemplateProps`.
     *
     * @example
     * ```tsx
     * const MyHeader = (props: AgentStepHeaderTemplateProps) => <div>{props.label}</div>;
     * <Reasoning headerTemplate={MyHeader} />
     * ```
     */
    headerTemplate?: React.ComponentType<AgentStepHeaderTemplateProps>;
    /**
     * A custom component that replaces the default step body area.
     * Receives `expanded`, `completed`, and `children`
     * via `AgentStepBodyTemplateProps`.
     *
     * @example
     * ```tsx
     * const MyBody = (props: AgentStepBodyTemplateProps) => <section>{props.children}</section>;
     * <Reasoning bodyTemplate={MyBody} />
     * ```
     */
    bodyTemplate?: React.ComponentType<AgentStepBodyTemplateProps>;
}
